        "type": "code-recipe",
        "id": "code-recipe-thinking-budget-gateway",
        "heading": "Code Recipe: Bộ điều phối AI Gateway tự chuẩn hóa Thinking Effort, Background >64K & Guardrail 272K",
        "language": "typescript",
        "filename": "src/ai/thinking-budget-gateway.ts",
        "description": "Hàm điều phối chuẩn hóa tham số trước khi gọi Google Interactions API (`@google/genai >= 3.2.0`) và OpenAI Responses API: tự động nâng `minimal` lên `low` nếu gặp `gemini-3.8-flash`/`gemini-4-argon`, bật `background: true` khi output > 65.536 trên Argon, tước bỏ `temperature`/`top_p` để tránh lỗi Interactions API, và chặn prompt vượt 210K token trước ngưỡng phụ phí 272K.",
        "code": "import { GoogleGenAI } from '@google/genai'; // Yeu cau @google/genai >= 3.2.0\n\ntype EffortLevel = 'minimal' | 'low' | 'medium' | 'high' | 'xhigh' | 'max';\n\ninterface DispatchRequest {\n  provider: 'google' | 'openai' | 'anthropic';\n  model: string;\n  effort: EffortLevel;\n  estimatedInputTokens: number;\n  maxOutputTokens: number;\n  previousInteractionId?: string;\n  prompt: string;\n}\n\nconst GEMINI_NO_MINIMAL = new Set([\n  'gemini-4-argon',\n  'gemini-3.8-flash',\n  'gemini-3.1-pro-preview',\n  'gemini-3.1-pro-preview-customtools',\n]);\n\nexport function sanitizeDispatchPolicy(req: DispatchRequest) {\n  let safeEffort = req.effort;\n\n  // 1. Chan bay HTTP 400: khong gui 'minimal' vao Argon / 3.8 Flash / 3.1 Pro\n  if (req.provider === 'google' && GEMINI_NO_MINIMAL.has(req.model)) {\n    if (safeEffort === 'minimal') safeEffort = 'low';\n    if (safeEffort === 'xhigh' || safeEffort === 'max') safeEffort = 'high';\n  }\n\n  // 2. Chan bay HTTP 400: Gemini 4 Argon > 65536 output bat buoc background=true\n  const requiresBackground =\n    req.model === 'gemini-4-argon' && req.maxOutputTokens > 65536;\n\n  if (req.model === 'gemini-4-argon') {\n    const totalUnified = req.estimatedInputTokens + req.maxOutputTokens;\n    if (totalUnified > 1_048_576) {\n      throw new Error(\n        `[BUDGET_OVERFLOW] Unified 1M pool exceeded: ${totalUnified} > 1048576`\n      );\n    }\n  }\n\n  // 3. Chan vach da phu phi 2x/1.5x (272K) & tran input GPT-5.3-Codex / 5.6\n  const shouldCompactFirst =\n    (req.model.startsWith('gpt-5.6') || req.model === 'gpt-5.3-codex') &&\n    req.estimatedInputTokens > 210_000;\n\n  // 4. Khoa tran xhigh cho model OpenAI de kiem soat reasoning_tokens gia output\n  const openaiReasoningEffort =\n    safeEffort === 'minimal' ? 'low' : safeEffort;\n\n  return {\n    safeEffort,\n    requiresBackground,\n    shouldCompactFirst,\n    openaiReasoningEffort,\n  };\n}\n\nexport async function callGeminiInteractionSafe(req: DispatchRequest) {\n  const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });\n  const policy = sanitizeDispatchPolicy(req);\n\n  if (policy.shouldCompactFirst) {\n    throw new Error('[COMPACTION_REQUIRED] Hay nen context truoc khi vuot 210K tokens.');\n  }\n\n  // Luu y: Interactions API v1 GA khong truyen temperature / top_p / top_k\n  const interaction = await ai.interactions.create({\n    model: req.model,\n    input: req.prompt,\n    previous_interaction_id: req.previousInteractionId,\n    store: true, // Giu trang thai 55 ngay cho goi tra phi de giam input lap lai\n    background: policy.requiresBackground,\n    generation_config: {\n      thinking_level: policy.safeEffort,\n      max_output_tokens: req.maxOutputTokens,\n    },\n  });\n\n  return {\n    interactionId: interaction.id,\n    status: interaction.status,\n    backgroundMode: policy.requiresBackground,\n  };\n}\n"
